insert:
property var animationImage
visible: !/^stat_notify_audio_track_(play|pause|(just_)?(rewind|fast_forward)|next|previous)\.png$/.test(String(animationImage))
property string currentImage:""
readonly property string imagePath:"qrc:/assets/images/"
width: icon.width
onAnimationImageChanged: {
if(animationImage.length > 0) {
currentImage =  imagePath + animationImage
} else {
currentImage = ""

}
Image{
id:icon
anchors.verticalCenter: parent.verticalCenter
fillMode: Image.PreserveAspectFit
source:currentImage
}
}
